/* Material Ripple */
.md-ripple {
    position: relative;
    overflow: hidden;
    cursor: pointer;
    user-select: none;
}

.md-ripple .ripple-effect {
    position: absolute;
    border-radius: 50%;
    background-color: rgba(255, 255, 255, 0.35);
    transform: scale(0);
    animation: ripple-animation 0.6s linear;
    pointer-events: none;
}

body[data-theme="v1"] .md-ripple .ripple-effect,
body[data-theme="v3"] .md-ripple .ripple-effect,
body[data-theme="v4"] .md-ripple .ripple-effect,
body[data-theme="v5"] .md-ripple .ripple-effect {
    background-color: rgba(103, 80, 164, 0.2);
}

@keyframes ripple-animation {
    to {
        transform: scale(4);
        opacity: 0;
    }
}

