    border-right: 1px solid var(--md-sys-color-outline-variant);
    display: flex;
    flex-direction: column;
    padding: 24px 16px;
    flex-shrink: 0;
    z-index: 100;
}

.brand {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 12px 24px 12px;
}

.brand-icon {
    width: 40px;
    height: 40px;
    background: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
    border-radius: var(--md-shape-radius);
    display: flex;
    align-items: center;
    justify-content: center;
}

.brand-icon svg {
    width: 24px;
    height: 24px;
    fill: currentColor;
}

.brand-title {
    font-size: 18px;
    font-weight: 700;
    color: var(--md-sys-color-on-surface);
    letter-spacing: -0.2px;
}

.brand-subtitle {
